export const dictionaries: Record<Locale, Record<string, string>> = { uk: {}, en: {}, ru: {} };
for (const [key, uk, en, ru] of entries) { dictionaries.uk[key] = uk; dictionaries.en[key] = en; dictionaries.ru[key] = ru; }
for (const direction of additionalDirections) for (const language of ['uk', 'en', 'ru'] as const) {
  dictionaries[language][`genres.${direction.slug}`] = direction.titles[language];
}
const sourceAliases: Record<string, string> = {'Рок':'genres.rock','Поп':'genres.pop','Альтернатива':'genres.alternative','Метал':'genres.metal','Хип-хоп / Рэп':'genres.hiphop','Танцевальная электроника':'genres.dance','R&B / Соул':'genres.rnb','Панк / Поп-панк':'genres.punk','Кантри':'genres.country','Джаз':'genres.jazz','Артисты Евровидения':'genres.eurovision','Евровидение':'genres.eurovision'};
for (const language of ['uk','en','ru'] as const) {
  for (const [alias,key] of Object.entries(sourceAliases)) dictionaries[language][alias] = dictionaries[language][key];
  for (const decade of ['70','80','90','00','10','20']) dictionaries[language][`Хиты ${decade}-х`] = dictionaries[language]['genres.era'].replace('{era}', decade);
  dictionaries[language]['Хиты нулевых'] = dictionaries[language]['genres.era'].replace('{era}', '00');
}
// A playback failure and a failed reset can arrive as two concatenated messages.
const sentenceKeys = entries.map(([key]) => key).filter(key => /[.!?]$/.test(key) && !key.includes('{')).sort((a,b) => b.length - a.length);
export const gameTranslationKeys = entries.filter(([key]) => !key.includes('.')).map(([key]) => key);
export function translate(locale: Locale, key: string, args: TranslationArgs = {}) {
  let value = dictionaries[locale][key] ?? dictionaries.uk[key];
  if (value === undefined) {
    let remainder = key; const parts: string[] = [];
    while (remainder) { const source = sentenceKeys.find(candidate => remainder === candidate || remainder.startsWith(`${candidate} `)); if (!source) break; parts.push(dictionaries[locale][source]); remainder = remainder.slice(source.length).trimStart(); }
    value = parts.length && !remainder ? parts.join(' ') : key;
  }
  return value.replace(/\{(\w+)\}/g, (original, name: string) => args[name] === undefined ? original : String(args[name]));
}
type I18nValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: string, args?: TranslationArgs) => string };
const I18nContext = createContext<I18nValue>({ locale: 'uk', setLocale: () => {}, t: (key, args) => translate('uk', key, args) });
export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>('uk');
  useEffect(() => {
    const frame = requestAnimationFrame(() => { try { const saved = localStorage.getItem('echo-locale'); if (saved === 'uk' || saved === 'en' || saved === 'ru') setLocaleState(saved); } catch {} });
    const update = (event: StorageEvent) => { if (event.key === 'echo-locale' && (event.newValue === 'uk' || event.newValue === 'en' || event.newValue === 'ru')) setLocaleState(event.newValue); };
    window.addEventListener('storage', update); return () => { cancelAnimationFrame(frame); window.removeEventListener('storage', update); };
  }, []);
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const setLocale = useCallback((value: Locale) => { setLocaleState(value); try { localStorage.setItem('echo-locale', value); } catch {} }, []);
  const t = useCallback((key: string, args?: TranslationArgs) => translate(locale, key, args), [locale]);
  const value = useMemo(() => ({ locale, setLocale, t }), [locale, setLocale, t]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}
export function useI18n() { return useContext(I18nContext); }
